#' Diagnostic Meta-Analysis: Study Review (Python)
#'
#' 
#' @param data .
#' @param study .
#' @param true_positives .
#' @param false_positives .
#' @param false_negatives .
#' @param true_negatives .
#' @param confidence_level .
#' @param reject_invalid .
#' @param show_studies .
#' @param show_excluded .
#' @param forest_plot .
#' @param plot_limit .
#' @param show_report .
#' @param show_explorer .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$studies} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$excluded} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$sensitivityPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$specificityPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$explorer} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$report} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pydiagnosticmeta <- function(
    data,
    study = NULL,
    true_positives = NULL,
    false_positives = NULL,
    false_negatives = NULL,
    true_negatives = NULL,
    confidence_level = 95,
    reject_invalid = FALSE,
    show_studies = TRUE,
    show_excluded = TRUE,
    forest_plot = FALSE,
    plot_limit = 20,
    show_report = FALSE,
    show_explorer = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pydiagnosticmeta requires jmvcore to be installed (restart may be required)")

    if ( ! missing(study)) study <- jmvcore::resolveQuo(jmvcore::enquo(study))
    if ( ! missing(true_positives)) true_positives <- jmvcore::resolveQuo(jmvcore::enquo(true_positives))
    if ( ! missing(false_positives)) false_positives <- jmvcore::resolveQuo(jmvcore::enquo(false_positives))
    if ( ! missing(false_negatives)) false_negatives <- jmvcore::resolveQuo(jmvcore::enquo(false_negatives))
    if ( ! missing(true_negatives)) true_negatives <- jmvcore::resolveQuo(jmvcore::enquo(true_negatives))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(study), study, NULL),
            `if`( ! missing(true_positives), true_positives, NULL),
            `if`( ! missing(false_positives), false_positives, NULL),
            `if`( ! missing(false_negatives), false_negatives, NULL),
            `if`( ! missing(true_negatives), true_negatives, NULL))


    options <- pydiagnosticmetaOptions$new(
        study = study,
        true_positives = true_positives,
        false_positives = false_positives,
        false_negatives = false_negatives,
        true_negatives = true_negatives,
        confidence_level = confidence_level,
        reject_invalid = reject_invalid,
        show_studies = show_studies,
        show_excluded = show_excluded,
        forest_plot = forest_plot,
        plot_limit = plot_limit,
        show_report = show_report,
        show_explorer = show_explorer,
        showConsole = showConsole)

    analysis <- pydiagnosticmetaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

